parameters.jsCode:
const text = $json.ai_response;

if (!text) {
  return [{
    json: {
      erro: 'ai_response está vazio ou nulo',
      valor_recebido: text
    }
  }];
}

const match = text.match(/\{[\s\S]*\}/);

if (!match) {
  return [{
    json: {
      erro: 'Nenhum JSON encontrado',
      resposta_original: text
    }
  }];
}

try {
  const data = JSON.parse(match[0]);

  return [{
    json: data
  }];
} catch (error) {
  return [{
    json: {
      erro: 'JSON inválido',
      mensagem: error.message,
      json_extraido: match[0]
    }
  }];
}

